import{_ as e,c as a,o as r,b0 as l}from"./chunks/framework.Dmsv_Tiv.js";const s="/media-docs/assets/640.DpQdsXvb.jpeg",n="/media-docs/assets/640-1719791329996-18.DtaMvHKm.webp",i="/media-docs/assets/640-1719791359734-21.3hxY4c-h.webp",o="/media-docs/assets/640-1719791378981-24.NgGPUmO3.webp",d="/media-docs/assets/640-1719791402605-27.zShmJnNH.webp",h="/media-docs/assets/640-1719791420325-30.B7XX_Gyo.webp",p="/media-docs/assets/640-1719877731760-4.D-TN9UrO.webp",c="/media-docs/assets/640-1719791123798-3.DN1kZyWa.webp",w="/media-docs/assets/640-1719791156073-6.B38edCHY.webp",g="/media-docs/assets/640-1719791188414-9.Cn9hrsc0.webp",m="/media-docs/assets/640-1719791222538-12.CNFllDUX.webp",_="/media-docs/assets/640-1719791246740-15.DN_dFjMc.webp",f="/media-docs/assets/640-1719109664739-3.CZD7Ve_u.jpg",b="/media-docs/assets/640-1719791636719-33.CLCemfm5.webp",x="/media-docs/assets/640-1719791760252-36.-v-ARQK1.webp",k="/media-docs/assets/640-1719791776336-39.BioalAM_.webp",y="/media-docs/assets/640-1719791797047-42.CFMgrvSi.webp",P="/media-docs/assets/640-1719791886043-45.C5jANkRx.webp",u="/media-docs/assets/640-1719791900888-48.BVhvAvkq.webp",E="/media-docs/assets/640-1719963281489-3.nVKrsITl.webp",B="/media-docs/assets/OIP-C-1719878027138-14.CUNQJ8JB.jpeg",A="/media-docs/assets/640-1719878067075-17.CDIBteMb.jpg",z="/media-docs/assets/640-1719878224818-20.HK4sEJt0.webp",I="/media-docs/assets/640-2-2407030735.DC2L6j5u.jpg",F="/media-docs/assets/640-1719963510987-6.BPuNl9rB.webp",D="/media-docs/assets/640-1719963589330-9.Bx6UaUy_.webp",q="/media-docs/assets/image-20240703074658024.CaeZLMD6.jpg",C="/media-docs/assets/image-20240703074611472.-7bEauYd.jpg",G="/media-docs/assets/640-1719964111125-14.fcgKYIcV.webp",S="/media-docs/assets/640-1719964203204-17.C_DYif5H.webp",M="/media-docs/assets/640-1719964344866-20.Cov-3PqH.webp",W="/media-docs/assets/640-202407040734.WHFcI3y9.webp",v="/media-docs/assets/640-1720049789367-4.D-FuL6Ht.png",N="/media-docs/assets/image-20240704073844279.fF1TYlMF.png",V="/media-docs/assets/640-1720050028460-8.gLlQXFOM.webp",K="/media-docs/assets/640-1720050106880-11.BcFQ5_Sk.webp",U=JSON.parse('{"title":"LV001-基础知识","description":null,"frontmatter":{"title":"LV001-基础知识","date":"2025-09-19T15:14:12.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/image/img-file-format/126b08d7a7343a17a5d362ea","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-09-19T15:14:12.929Z","fulluuid":"7a5d362ea57c483c9dd1172de0984cbd","useduuid":"7a5d362ea"}},"headers":[],"relativePath":"sdoc/image/img-file-format/126b08d7a7343a17a5d362ea.md","filePath":"sdoc/01-图像/30-图像文件格式/LV001-基础知识.md","lastUpdated":1767537778000}'),R={name:"sdoc/image/img-file-format/126b08d7a7343a17a5d362ea.md"};function T(L,t,X,j,J,H){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="lv001-基础知识" tabindex="-1">LV001-基础知识 <a class="header-anchor" href="#lv001-基础知识" aria-label="Permalink to &quot;LV001-基础知识&quot;">​</a></h1><h2 id="一、两种类型的图片" tabindex="-1">一、两种类型的图片 <a class="header-anchor" href="#一、两种类型的图片" aria-label="Permalink to &quot;一、两种类型的图片&quot;">​</a></h2><p>经常会听到说位图和矢量图这种词语，我们先来了解一下这两个概念。</p><h3 id="_1-位图" tabindex="-1">1. 位图 <a class="header-anchor" href="#_1-位图" aria-label="Permalink to &quot;1. 位图&quot;">​</a></h3><h4 id="_1-1-基本概念" tabindex="-1">1.1 基本概念 <a class="header-anchor" href="#_1-1-基本概念" aria-label="Permalink to &quot;1.1 基本概念&quot;">​</a></h4><p><strong><a href="https://www.wikiwand.com/zh-hans/%E4%BD%8D%E5%9B%BE" target="_blank" rel="noreferrer">位图（bitmap image）</a></strong>：是使用<a href="https://www.wikiwand.com/zh-hans/%E5%83%8F%E7%B4%A0" target="_blank" rel="noreferrer">像素</a><a href="https://www.wikiwand.com/zh-hans/%E6%95%B0%E7%BB%84" target="_blank" rel="noreferrer">数组</a>(Pixel-array/Dot-matrix点阵)来表示的<a href="https://www.wikiwand.com/zh-hans/%E5%9B%BE%E5%83%8F" target="_blank" rel="noreferrer">图像</a>。也可以叫像素图、栅格图（raster image）或点阵图、光栅图。其中与<strong>栅格图</strong>（Raster graphics）的概念类似，但有细微不同。</p><p>位图的像素都分配有特定的位置和<a href="https://www.wikiwand.com/zh-hans/%E9%A2%9C%E8%89%B2" target="_blank" rel="noreferrer">颜色</a>值。每个像素的颜色信息由<a href="https://www.wikiwand.com/zh-hans/%E4%B8%89%E5%8E%9F%E8%89%B2%E5%85%89%E6%A8%A1%E5%BC%8F" target="_blank" rel="noreferrer">RGB</a>组合或者灰度值表示。根据<a href="https://www.wikiwand.com/zh-hans/%E8%89%B2%E5%BD%A9%E6%B7%B1%E5%BA%A6" target="_blank" rel="noreferrer">色彩深度</a>，可将位图分为1、4、8、16、24及32<a href="https://www.wikiwand.com/zh-hans/%E4%BD%8D%E5%85%83" target="_blank" rel="noreferrer">位</a>图像等。每个像素使用的信息位数越多，可用的颜色就越多，颜色表现就越逼真，相应的数据量越大。例如，位深度为 1 的像素位图只有两个可能的值（黑色和白色），所以又称为二值位图。位深度为 8 的图像有 28（即 256）个可能的值。位深度为 8 的灰度模式图像有 256 个可能的灰色值。</p><p>RGB图像由三个颜色通道组成。8 位/通道的 RGB 图像中的每个通道有 256 个可能的值，这意味着该图像有 1600 万个以上可能的颜色值。有时将带有 8 位/通道 (bpc) 的 RGB 图像称作 24 位图像（8 位 x 3 通道 = 24 位数据/像素）。通常将使用24位RGB组合数据位表示的位图称为<a href="https://www.wikiwand.com/zh-hans/%E7%9C%9F%E5%BD%A9%E8%89%B2" target="_blank" rel="noreferrer">真彩色</a>位图。</p><p>通过捕捉得到的图像（如拍摄、截图）都是像素图。像素文件常见的图片格式包括<strong>BMP、PNG、GIF、WEBP、TIFF</strong>等。图片的分辨率直接关系着图片的质量，分辨率越高，图像质量越好，而且文件占的储存空间大，放大图片时图片的质量会下降，放大会出现锯齿。</p><img src="'+s+'" alt="图片" style="zoom:50%;"><p>位图图像的特点是可以表现色彩的变化和颜色的细微过渡，产生逼真的效果，但其缺点是图片放大会失真。位图图像的文件大小与其分辨率有关，分辨率越高，图像越清晰，但相应的文件大小也越大。位图图像因其色彩丰富、分辨率依赖性强、文件大小可调以及打印质量易于优化等特点，更适合于打印输出。</p><h4 id="_1-2-特点" tabindex="-1">1.2 特点 <a class="header-anchor" href="#_1-2-特点" aria-label="Permalink to &quot;1.2 特点&quot;">​</a></h4><p>高质量图像细节：位图可以呈现高质量的图像细节，因为它们使用像素点的阵列来表示图像。每个像素点都可以具有不同的颜色和亮度值，使得位图可以呈现出更为精细的图像。</p><p>高级图像处理技术：位图支持许多高级的图像处理技术，例如反锯齿、阴影、透明度和渐变等。这使得位图图像在很多场景中都具有不可替代的优势，例如在数字艺术、游戏开发、电影特效和印刷等领域。</p><p>无损压缩：位图可以被无损压缩，这意味着它们可以通过减小图像文件的大小而不会失去图像的任何细节和质量。这使得位图图像非常适合在需要高质量图像的同时需要节省存储空间的情况下使用。</p><p>广泛的兼容性：几乎所有图像处理和图形设计软件都支持位图。这使得位图图像在不同的平台和应用程序之间具有很好的互操作性。</p><p>丰富的色彩表现力：位图可以表现出色彩的变化和颜色的细微过渡，从而产生非常逼真的效果。这对于需要处理真实世界照片或图像的场景尤其重要。</p><p>灵活的图像处理：由于位图是直接由像素组成的，因此在进行图像处理时（如滤镜效果、色彩调整等），可以很方便地对每个像素进行操作。这对于需要处理大量图像数据的场景（如照片编辑、图形设计等）非常有用。</p><p>适应性强：位图图像广泛应用于各种领域，如数码摄影、扫描仪和其他数码设备的图像存储和显示，也被用于网页设计、平面设计、视频游戏等领域。</p><p>综上所述，位图作为一种常见的图像格式，其优势在于能够提供高质量的图像细节、支持先进的图像处理技术、实现无损压缩、具有广泛的兼容性、丰富的色彩表现力以及灵活的图像处理能力。这些特点使得位图在许多应用场景中都非常实用和受欢迎。</p><h4 id="_1-3-应用场景" tabindex="-1">1.3 应用场景 <a class="header-anchor" href="#_1-3-应用场景" aria-label="Permalink to &quot;1.3 应用场景&quot;">​</a></h4><ul><li>图像处理</li></ul><p>位图图像非常适合于照片的处理，因为照片需要用到色阶较多的场景，因此使用位图图像存储方式可以记录每一个像素的颜色值，从而更好地表达照片的细节。常用格式：RAW、JPG、PNG、GIF、TIF、BMP。</p><img src="'+n+'" alt="图片" style="zoom:25%;"><ul><li>图像显示</li></ul><p>位图图像可以用于图像显示，如数码相机拍摄的照片、扫描仪扫描的图片以及计算机截屏图等，在很多投屏显示中所用的图片大多数位图图片。常用格式：JPG、PNG、GIF。</p><img src="'+i+'" alt="图片" style="zoom:25%;"><ul><li>设计印刷出版</li></ul><p>由于位图图片的海量信息来源，在广告及图文设计方面得到大量应用，同时印刷出版中不可避免的会使用位图图片。常用格式：TIF、PSD、JPG、PNG。</p><img src="'+o+'" alt="图片" style="zoom:35%;"><ul><li>互联网应用</li></ul><p>由于互联网的普及特别是移动互联网的普及，日常生活中在社交媒体、手机客户端等媒体应用浏览图片，发布图片多用到位图图片，相比矢量图网页设计中的位图图片占比70~80%。常用格式：JPG、PNG、GIF、WEBP。</p><img src="'+d+'" alt="图片" style="zoom:25%;"><ul><li>三维设计及渲染</li></ul><p>用于三维设计的材质创建，UV贴图，几乎用的都是位图图片，如常见的PNG、JPG等格式。</p><img src="'+h+'" alt="图片" style="zoom:45%;"><h3 id="_2-矢量图" tabindex="-1">2. 矢量图 <a class="header-anchor" href="#_2-矢量图" aria-label="Permalink to &quot;2. 矢量图&quot;">​</a></h3><h4 id="_2-1-基本概念" tabindex="-1">2.1 基本概念 <a class="header-anchor" href="#_2-1-基本概念" aria-label="Permalink to &quot;2.1 基本概念&quot;">​</a></h4><p><a href="https://www.wikiwand.com/zh-hans/%E7%9F%A2%E9%87%8F%E5%9B%BE%E5%BD%A2" target="_blank" rel="noreferrer">矢量图形</a>：是<a href="https://www.wikiwand.com/zh-hans/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9B%BE%E5%BD%A2%E5%AD%A6" target="_blank" rel="noreferrer">计算机图形学</a>中用<a href="https://www.wikiwand.com/zh-hans/%E7%82%B9" target="_blank" rel="noreferrer">点</a>、<a href="https://www.wikiwand.com/zh-hans/%E7%9B%B4%E7%BA%BF" target="_blank" rel="noreferrer">直线</a>或者<a href="https://www.wikiwand.com/zh-hans/%E5%A4%9A%E8%BE%B9%E5%BD%A2" target="_blank" rel="noreferrer">多边形</a>等基于数学方程的几何图元表示的<a href="https://www.wikiwand.com/zh-hans/%E5%9B%BE%E5%83%8F" target="_blank" rel="noreferrer">图像</a>。最直接的叫法为“图形”，可以改变它的颜色、形状、轮廓、大小和屏幕位置等。它是根据几何特性来绘制图形，可以是一个点或者一条线。</p><p>矢量图使用笛卡尔平面上的直线和曲线系统，与位图不同，矢量图不是由像素点组成，即通过数学公式计算获得的线段、曲线和多边形等基本几何形状组成，由坐标系统获得图像边界，该系统相对于总面积（而不是任何单个像素）进行缩放。基于矢量的图形，每个矢量包含起点、终点、颜色和其他属性信息。矢量图像的特点是放大后图像不会失真，与分辨率无关，适用于图形设计、文字设计和一些标志设计、版式设计等。矢量图的主要优势在于其可伸缩性、编辑性和小文件体积。</p><p>最常见的矢量文件类型有<strong>AI</strong> (Adobe Illustrator)、<strong>EPS</strong> (Encapsulated PostScript)和 <strong>SVG</strong> (Scalable Vector Graphics)。这些格式可以被许多设计软件和绘图工具支持，如Pixso、Adobe Illustrator、CorelDRAW和Inkscape等。</p><h4 id="_2-2-特点" tabindex="-1">2.2 特点 <a class="header-anchor" href="#_2-2-特点" aria-label="Permalink to &quot;2.2 特点&quot;">​</a></h4><p>可伸缩性：矢量图可以根据需要无限缩放，而不会损失图像质量，这在需要适应不同尺寸和分辨率的场合非常有用。</p><p>编辑性：矢量图易于编辑和修改，因为它们由一系列路径、线条和形状组成，可以通过图形设计软件进行精确编辑。</p><p>文件体积：矢量图文件通常较小，因为它们仅包含图像的数学描述，而不是每个像素点的颜色信息，这使得它们在网络传输速度更快，并且占用更少的存储空间。</p><p>总的来说，矢量图是一种强大的图像类型，具备众多优点，适用于多种应用领域。它们提供高质量、可编辑和可缩放的图像解决方案，因此在图形设计和多媒体制作中非常有价值。</p><h4 id="_2-3-应用场景" tabindex="-1">2.3 应用场景 <a class="header-anchor" href="#_2-3-应用场景" aria-label="Permalink to &quot;2.3 应用场景&quot;">​</a></h4><p>矢量图因其可编辑性强、文件大小小、清晰度高等优点，在需要频繁调整尺寸、颜色或形状的设计场景中尤为适用。</p><ul><li>标志、图标设计</li></ul><p>品牌标识、标志、图标之类的图形需要在不同场合使用放大或缩小，同时大部分都是简单的醒目的色块，造型抽象简洁为主，因此对矢量图的需求特别大，大部分的品牌标识LOGO，图标等都是采用矢量图设计表达。常用格式：AI、CDR。</p><img src="'+p+'" alt="图片" style="zoom:25%;"><ul><li>图形和图表设计</li></ul><p>矢量图的清晰度和可编辑性使其成为图形和图表设计的理想选择，如科学插图、流程图和统计图表等。常用软件生成如：Excel、VISO、PPT、PDF。</p><img src="'+c+'" alt="图片" style="zoom:35%;"><ul><li>界面和图标设计</li></ul><p>矢量图在用户界面设计中非常有用，尤其是在移动设备和应用程序中，因为它们可以轻松适应不同的分辨率和尺寸。常用设计软件如：Adobe Illustrator、Corel Draw、Sketch、Inkscape、Adobe XD、Canva。</p><img src="'+w+'" alt="图片" style="zoom:18%;"><ul><li>广告宣传印刷</li></ul><p>矢量图可以用于广告设计，如海报、宣传册和户外广告，因为它们即使在放大时也能保持清晰度。常用设计软件如：Adobe Illustrator、CorelDraw、InDesign。</p><img src="'+g+'" alt="图片" style="zoom:33%;"><ul><li>动画和游戏设计</li></ul><p>矢量图在动画和游戏设计中也很有用，因为它们可以创建平滑的动画效果和复杂的图形界面。常用设计软件如：Synfig Studio、Adobe Animate（原Flash）、Toon Boom Harmony、Inkscape、After Effects等。</p><img src="'+m+'" alt="图片" style="zoom:30%;"><ul><li>网站和互联网内容</li></ul><p>矢量图可以用于网站和社交媒体内容，因为它们可以轻松适应不同的分辨率和尺寸，同时保持高质量的视觉效果。常用格式：SVG、EPS、PDF。</p><img src="'+_+'" alt="图片" style="zoom:70%;"><h3 id="_3-两者的对比" tabindex="-1">3. 两者的对比 <a class="header-anchor" href="#_3-两者的对比" aria-label="Permalink to &quot;3. 两者的对比&quot;">​</a></h3><p>最直观的区别如下：</p><img src="'+f+'" alt="图片" style="zoom:33%;"><h3 id="_4-位图转换为矢量图" tabindex="-1">4. 位图转换为矢量图？ <a class="header-anchor" href="#_4-位图转换为矢量图" aria-label="Permalink to &quot;4. 位图转换为矢量图？&quot;">​</a></h3><p>要将位图转换为矢量图，可以使用以下几种方法和工具：</p><ul><li><p>在线工具：如Vectorizer.AI，这是一个基于人工智能的在线工具，可以将JPG/PNG位图快速转换成SVG格式的矢量图，适合设计人员对图片进行二次编辑和上色。另一个类似的工具是Convertio，它可以实现位图到矢量图的转换，包括SVG格式。</p></li><li><p>桌面应用程序：如Vector Magic Desktop Edition，这款应用程序能够轻松将位图图片转换成矢量图输出，并支持多种矢量图格式，如EPS、SVG、PDF、PNG等。</p></li><li><p>Adobe Photoshop：虽然Photoshop主要是位图处理软件，但它也有将位图文件输出为矢量文件的功能。可以通过图像描摹功能，选择高保真或低保真度照片进行转换。</p></li><li><p>CorelDRAW：CorelDRAW的轮廓描摹功能也可以将位图文件转换为矢量图形，用户可以选择不同的图像类型效果，以达到最佳转换效果。</p></li><li><p>Adobe Illustrator: Adobe Illustrator的轮廓描摹功能建立并扩展将位图文件转换为矢量图形，用户可以选择不同的精度类型比对效果，以达到最佳转换效果。</p></li></ul><p>在使用这些工具时，需要注意转换效果可能会受到原始位图质量的影响，有时可能需要手动调整以达到理想效果。此外，对于复杂图案的转换，可能需要更多的细节处理才能获得满意的结果。</p><h2 id="二、常见文件扩展名" tabindex="-1">二、常见文件扩展名 <a class="header-anchor" href="#二、常见文件扩展名" aria-label="Permalink to &quot;二、常见文件扩展名&quot;">​</a></h2><blockquote><p>注意：不一定很全！！！</p></blockquote><h3 id="_1-位图-1" tabindex="-1">1. 位图 <a class="header-anchor" href="#_1-位图-1" aria-label="Permalink to &quot;1. 位图&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/%E6%96%87%E4%BB%B6%E6%89%A9%E5%B1%95%E5%90%8D" target="_blank" rel="noreferrer">扩展名</a></th><th style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/MIME" target="_blank" rel="noreferrer">MIME</a> 类型</th><th style="text-align:center;">固有名称</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:center;">.<a href="https://www.wikiwand.com/zh-hans/BMP" target="_blank" rel="noreferrer">bmp</a></td><td style="text-align:center;">image/bmp</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/Windows" target="_blank" rel="noreferrer">Windows</a><a href="https://www.wikiwand.com/zh-hans/%E4%BD%8D%E5%9B%BE" target="_blank" rel="noreferrer">位图</a></td><td style="text-align:left;">最常被<a href="https://www.wikiwand.com/zh-hans/Microsoft_Windows" target="_blank" rel="noreferrer">Microsoft Windows</a> 程序以及其本身使用的格式。可以使用无损的资料压缩，但是一些程序只能使用未经压缩的文件。</td></tr><tr><td style="text-align:center;">.iff .ilbm</td><td style="text-align:center;">?</td><td style="text-align:center;">互换档案格式（Interchange file format / Interleave bitmap）</td><td style="text-align:left;">在Amiga机上很受欢迎。ILBM是<a href="https://www.wikiwand.com/zh-hans/IFF" target="_blank" rel="noreferrer">IFF</a>的图表类型格式，可以包含更多的图片。</td></tr><tr><td style="text-align:center;">.tiff, .tif</td><td style="text-align:center;">image/tiff</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/%E6%A0%87%E7%AD%BE%E5%9B%BE%E5%83%8F%E6%96%87%E4%BB%B6%E6%A0%BC%E5%BC%8F" target="_blank" rel="noreferrer">标签图像文件格式</a></td><td style="text-align:left;">大量的用于传统影像印刷，可进行有损或无损压缩，但是很多程序只支持可选项目的一部分功能。</td></tr><tr><td style="text-align:center;">.<a href="https://www.wikiwand.com/zh-hans/PNG" target="_blank" rel="noreferrer">png</a></td><td style="text-align:center;">image/png</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/PNG" target="_blank" rel="noreferrer">便携式网络图片</a></td><td style="text-align:left;">无损压缩位图格式。起初被设计用于代替在互联网上的GIF格式文件。与GIF的专利权没有关联。</td></tr><tr><td style="text-align:center;">.<a href="https://www.wikiwand.com/zh-hans/GIF" target="_blank" rel="noreferrer">gif</a></td><td style="text-align:center;">image/gif</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/GIF" target="_blank" rel="noreferrer">图形交换格式</a></td><td style="text-align:left;">在网络上广泛使用，但有时也会因为专利权的原因而不使用该图形格式。支持动画图像，支持256色，对真彩图片进行有损压缩。使用多祯可以提高颜色准确度。</td></tr><tr><td style="text-align:center;">.jpeg .jpg</td><td style="text-align:center;">image/jpeg</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/JPEG" target="_blank" rel="noreferrer">联合专家组</a></td><td style="text-align:left;">在网路上广泛用于储存相片。使用有损压缩，图片品质可根据压缩的设定而有所不同。</td></tr><tr><td style="text-align:center;">.mng</td><td style="text-align:center;">video/x-mng</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/%E5%A4%9A%E9%87%8D%E7%B6%B2%E7%B5%A1%E5%9C%96%E5%BD%A2" target="_blank" rel="noreferrer">Multiple-image Network Graphics</a></td><td style="text-align:left;">使用类似于PNG和JPEG的资料流动的动画格式，起初被设计成GIF的替代格式。与GIF的专利权没有联系。</td></tr><tr><td style="text-align:center;">.xpm</td><td style="text-align:center;">image/x-xpm</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/X_Pixmap" target="_blank" rel="noreferrer">X Pixmap</a></td><td style="text-align:left;">在UNIX平台的X Windows System下使用广泛的格式。一种不使用压缩的ASCII格式。</td></tr><tr><td style="text-align:center;">.<a href="https://www.wikiwand.com/zh-hans/PSD" target="_blank" rel="noreferrer">psd</a></td><td style="text-align:center;">?</td><td style="text-align:center;">Photoshop文件</td><td style="text-align:left;"><a href="https://www.wikiwand.com/zh-hans/Photoshop" target="_blank" rel="noreferrer">Photoshop</a>文件的标准格式。有很多诸如图层的额外功能。其它软件少有支持。</td></tr><tr><td style="text-align:center;">.sai</td><td style="text-align:center;">?</td><td style="text-align:center;"></td><td style="text-align:left;"><a href="https://www.wikiwand.com/zh-hans/Paint_Tool_SAI" target="_blank" rel="noreferrer">Paint_Tool_SAI</a>文件的标准格式。有很多诸如图层的额外功能。其它软件少有支持。</td></tr><tr><td style="text-align:center;">.psp</td><td style="text-align:center;">?</td><td style="text-align:center;">Paint Shop Pro文件</td><td style="text-align:left;"><a href="https://www.wikiwand.com/zh-hans/Paint_Shop_Pro" target="_blank" rel="noreferrer">Paint Shop Pro</a>文件的标准格式，类似于为Photoshop的.psd。被很少软件支持。</td></tr><tr><td style="text-align:center;">.ufo</td><td style="text-align:center;">?</td><td style="text-align:center;">PhotoImpact文件</td><td style="text-align:left;"><a href="https://www.wikiwand.com/zh-hans/PhotoImpact" target="_blank" rel="noreferrer">PhotoImpact</a>文件的标准格式，类似于为Photoshop的.psd。Corel出品的相关影像、图片编辑软体皆可支援。</td></tr><tr><td style="text-align:center;">.xcf</td><td style="text-align:center;">?</td><td style="text-align:center;">eXperimental Computing Facility</td><td style="text-align:left;">具有很多诸如图层的额外特性，主要使用于<a href="https://www.wikiwand.com/zh-hans/GIMP" target="_blank" rel="noreferrer">GIMP</a>，但是也可以被<a href="https://www.wikiwand.com/zh-hans/ImageMagick" target="_blank" rel="noreferrer">ImageMagick</a>等软体读取。</td></tr><tr><td style="text-align:center;">.<a href="https://www.wikiwand.com/zh-hans/PCX" target="_blank" rel="noreferrer">pcx</a></td><td style="text-align:center;">image/pcx</td><td style="text-align:center;">PCX文件（ZSoft Paint）</td><td style="text-align:left;">一种较早出现的位图图形文件格式，用长度游程算法（RLE, Run-Length Encode）压缩，支持1位、8位和24位颜色。</td></tr><tr><td style="text-align:center;">.ppm</td><td style="text-align:center;">?</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/Portable_Pixmap_File_Format" target="_blank" rel="noreferrer">Portable Pixmap Format</a></td><td style="text-align:left;">很简单的图形格式，使用于交换位图。</td></tr><tr><td style="text-align:center;">.WebP</td><td style="text-align:center;">image/webp</td><td style="text-align:center;"></td><td style="text-align:left;">同时提供了有损压缩与无损压缩（可逆压缩）的图片文件格式。<a href="https://www.wikiwand.com/zh-hans/Google" target="_blank" rel="noreferrer">Google</a>出品的相关产品皆可支持。</td></tr></tbody></table><h3 id="_2-矢量图形" tabindex="-1">2. 矢量图形 <a class="header-anchor" href="#_2-矢量图形" aria-label="Permalink to &quot;2. 矢量图形&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/%E6%96%87%E4%BB%B6%E6%89%A9%E5%B1%95%E5%90%8D" target="_blank" rel="noreferrer">扩展名</a></th><th style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/MIME" target="_blank" rel="noreferrer">MIME</a>类型</th><th style="text-align:center;">固有名</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:center;">.ps</td><td style="text-align:center;">application/postscript</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/PostScript" target="_blank" rel="noreferrer">PostScript</a></td><td style="text-align:left;">属于基于矢量页面描述语言，由Adobe研制和拥有。Postscript是强大的stack-based<a href="https://www.wikiwand.com/zh-hans/%E7%BC%96%E7%A8%8B%E8%AF%AD%E8%A8%80" target="_blank" rel="noreferrer">编程语言</a>。受很多激光打印机支持。</td></tr><tr><td style="text-align:center;">.eps</td><td style="text-align:center;">?</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/Encapsulated_PostScript" target="_blank" rel="noreferrer">Encapsulated PostScript</a></td><td style="text-align:left;">一个描述小型矢量图的PostScript文件，对比与描述整页的文件格式。</td></tr><tr><td style="text-align:center;">.pdf</td><td style="text-align:center;">application/pdf</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/PDF" target="_blank" rel="noreferrer">便携式文件格式</a></td><td style="text-align:left;">一个简化的PostScript版本，允许包含有多页和链接的文件。与<a href="https://www.wikiwand.com/zh-hans/Adobe_Acrobat" target="_blank" rel="noreferrer">Adobe Acrobat</a> Reader或Adobe eBook Reader配合使用。</td></tr><tr><td style="text-align:center;">.ai</td><td style="text-align:center;">application/illustrator</td><td style="text-align:center;">Adobe Illustrator Document</td><td style="text-align:left;"><a href="https://www.wikiwand.com/zh-hans/Adobe_Illustrator" target="_blank" rel="noreferrer">Adobe Illustrator</a>使用的矢量格式。</td></tr><tr><td style="text-align:center;">.fh</td><td style="text-align:center;">?</td><td style="text-align:center;">Adobe Freehand Document</td><td style="text-align:left;"><a href="https://www.wikiwand.com/zh-hans/Adobe_Freehand" target="_blank" rel="noreferrer">Adobe Freehand</a>使用的矢量格式。</td></tr><tr><td style="text-align:center;">.swf</td><td style="text-align:center;">application/x-shockwave-flash</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/Macromedia_Flash" target="_blank" rel="noreferrer">Flash</a></td><td style="text-align:left;">Flash是用来播放包含在SWF文件中的矢量动画的浏览器插件。有几种应用程序可以创建SWF文件，包括由Macromedia发布的Flash。</td></tr><tr><td style="text-align:center;">.fla</td><td style="text-align:center;">?</td><td style="text-align:center;">Flash Source File</td><td style="text-align:left;">Shockwave Flash源文件，只能使用于Macromedia Flash或<a href="https://www.wikiwand.com/zh-hans/Adobe_Flash" target="_blank" rel="noreferrer">Adobe Flash</a>软件。</td></tr><tr><td style="text-align:center;">.svg</td><td style="text-align:center;">image/svg+xml</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/SVG" target="_blank" rel="noreferrer">Scalable Vector Graphics</a></td><td style="text-align:left;">一个基于<a href="https://www.wikiwand.com/zh-hans/XML" target="_blank" rel="noreferrer">XML</a>的矢量图格式，由<a href="https://www.wikiwand.com/zh-hans/World_Wide_Web_Consortium" target="_blank" rel="noreferrer">World Wide Web Consortium</a>为浏览器定义的标准。</td></tr><tr><td style="text-align:center;">.wmf</td><td style="text-align:center;">image/x-wmf</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/Windows_Metafile" target="_blank" rel="noreferrer">Windows图元文件格式</a></td><td style="text-align:left;">作为<a href="https://www.wikiwand.com/zh-hans/%E5%BE%AE%E8%BD%AF" target="_blank" rel="noreferrer">微软</a>操作系统存储矢量图和光栅图的格式。</td></tr><tr><td style="text-align:center;">.dxf</td><td style="text-align:center;">image/vnd.dxf</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/ASCII_Drawing_Interchange_file_format" target="_blank" rel="noreferrer">ASCII Drawing Interchange</a></td><td style="text-align:left;">为<a href="https://www.wikiwand.com/zh-hans/%E8%AE%A1%E7%AE%97%E6%9C%BA%E8%BE%85%E5%8A%A9%E8%AE%BE%E8%AE%A1" target="_blank" rel="noreferrer">CAD</a>程序存储矢量图的标准ASCII<a href="https://www.wikiwand.com/zh-hans/%E6%96%87%E6%9C%AC%E6%96%87%E4%BB%B6" target="_blank" rel="noreferrer">文本文件</a>。</td></tr><tr><td style="text-align:center;">.cgm</td><td style="text-align:center;">image/cgm</td><td style="text-align:center;"><a href="https://www.wikiwand.com/zh-hans/CGM" target="_blank" rel="noreferrer">CGM</a></td><td style="text-align:left;"><a href="https://www.wikiwand.com/zh-hans/ISO" target="_blank" rel="noreferrer">ISO</a>标准，在1990年代非常普遍，曾是是业界的档案交换标准。但因为新一代更好的格式（如svg）出现，今日在实际中几乎没有再使用。</td></tr></tbody></table><h3 id="_3-技术细节" tabindex="-1">3. 技术细节 <a class="header-anchor" href="#_3-技术细节" aria-label="Permalink to &quot;3. 技术细节&quot;">​</a></h3><p><a href="https://www.wikiwand.com/zh-hans/%E5%9B%BE%E5%83%8F%E6%96%87%E4%BB%B6%E6%A0%BC%E5%BC%8F%E6%AF%94%E8%BE%83#%E6%8A%80%E6%9C%AF%E7%BB%86%E8%8A%82" target="_blank" rel="noreferrer">图形文件格式比较 - Wikiwand</a></p><h2 id="三、基本概念" tabindex="-1">三、基本概念 <a class="header-anchor" href="#三、基本概念" aria-label="Permalink to &quot;三、基本概念&quot;">​</a></h2><h3 id="_1-什么是像素" tabindex="-1">1. 什么是像素 <a class="header-anchor" href="#_1-什么是像素" aria-label="Permalink to &quot;1. 什么是像素&quot;">​</a></h3><p><a href="https://www.wikiwand.com/zh-hans/%E5%83%8F%E7%B4%A0" target="_blank" rel="noreferrer"><strong>像素</strong></a>，为影像显示的基本单位，译自英文“<strong>pixel</strong>”，<strong>pix</strong>是英语单词picture的常用简写，加上英语单词“元素”<strong>el</strong>ement，就得到<strong>pixel</strong>，故“像素”表示“画像元素”之意，有时亦被称为<strong>pel</strong>（<strong>p</strong>icture <strong>el</strong>ement）。</p><p>可以理解为一个最小图像单元（只能涂一个颜色）的小方块，就是1px，是一小块面积，但是一般并不强调面积的大小，只是说这是一个最小单元。1px是一个小方块，但是这个小方块的边长却不是固定的，不同的图片、显示设备都可能是不同的，甚至这个小方块可以是长方形，就是说表示为1px的小方块的宽和高，真实对应的长度可能是不同的。</p><h3 id="_2-什么是分辨率" tabindex="-1">2. 什么是分辨率 <a class="header-anchor" href="#_2-什么是分辨率" aria-label="Permalink to &quot;2. 什么是分辨率&quot;">​</a></h3><p>分辨率一般可以分为显示分辨率和图像分辨率两类。</p><ul><li><p>显示分辨率也就是屏幕分辨率，我们平时手机配置中支持分辨率1920*1080，是指硬件屏幕支持水平1920线逐行扫描，在垂直方向上支持垂直1080线逐行扫描，和硬件性能相关。</p></li><li><p>图像分辨率用在印刷上单位为DPI，指的是每英寸的墨点数，用在显示屏上单位为PPI(Pixel per inch)，指的是每英寸的像素数，并不是用数字×数字去表示，而是一个数字，例如300PPI，指的是每英寸有300像素，一块电子屏，在显示分辨率不变的情况下，屏幕越小则说明像素分辨率越大，图像也就越清晰细腻，例如同样1920×1080的显示屏，电脑显示器的尺寸比手机屏大很多，电脑显示器的图像分辨率是72，而手机能达到300多，苹果的视网膜屏就是这个意思。</p></li></ul><h4 id="_2-1-基本概念-1" tabindex="-1">2.1 基本概念 <a class="header-anchor" href="#_2-1-基本概念-1" aria-label="Permalink to &quot;2.1 基本概念&quot;">​</a></h4><p>分辨率，简单来说，就是单位尺寸或面积内像素点的数量。在数字图像中，分辨率通常以像素（Pixels）为单位来衡量。对于扫描仪和打印机等设备，分辨率则是以每英寸点数（DPI，Dots Per Inch或PPI，Point Per Inch）或每厘米点数（DPC，Dots Per Centimeter）来表示。</p><img src="'+b+'" alt="图片"><h4 id="_2-2-图片的本质" tabindex="-1">2.2 图片的本质？ <a class="header-anchor" href="#_2-2-图片的本质" aria-label="Permalink to &quot;2.2 图片的本质？&quot;">​</a></h4><img src="'+x+'" alt="图片"><p>图片由像素单元组成，每一个像素单元记录了一份图像信息，因此，图片是信息的一种载体，分辨率等同于信息密度。单位尺寸内信息密度越高，图像的细节越多，图片越清晰，相应的分辨率越高。</p><p>而信息的本质是一切宇宙万物的基本单元。数学家香农（Claude E.Shannon）指出：“信息是用来消除随机不定性的东西”，因此图片的本质就是为了消除空间中随机不定的图像信息而产生的信息集合。这些信息以一定的规律有效的组合起来而产生图像，即用二维的图形化方式存储信息和表达图像信息。</p><p>上面已经大概了解过了，图片的类型有矢量图和点阵图（又称位图）两种类型，矢量图因为是空间位置的信息表达，没有分辨率概念，后面的学习都是指位图。之后的笔记中“图片”即指点阵图和位图。</p><ul><li>72dpi的图片</li></ul><img src="'+k+'" alt="图片" style="zoom:80%;"><p>上面的72dpi的图片局部放大如下图：</p><img src="'+y+'" alt="图片" style="zoom:50%;"><ul><li>600dpi的图片</li></ul><img src="'+P+'" alt="图片" style="zoom:80%;"><p>局部放大后如下图：</p><img src="'+u+'" alt="图片" style="zoom:50%;"><p>上图示例可知分辨率越高，图片信息量越多，图片越清晰。</p><p>在高清扫描中，高分辨率意味着扫描设备能够捕捉到更多的细节，使图像更接近原物。而在高清打印输出中，高分辨率则保证了图像在物理呈现上还原数字信息，高清打印的还原精度能保障输出的图像依然能保持清晰，避免出现锯齿状或模糊的现象。</p><p>总的来说，分辨率是理解和评价图片质量的关键。无论是从扫描还是打印的角度，我们都应深入理解并准确应用分辨率的相关知识。只有这样，我们才能更好地欣赏和利用数字图像带来的视觉享受。</p><h4 id="_2-3-分辨率-从概念到应用" tabindex="-1">2.3 分辨率：从概念到应用 <a class="header-anchor" href="#_2-3-分辨率-从概念到应用" aria-label="Permalink to &quot;2.3 分辨率：从概念到应用&quot;">​</a></h4><p>数字化的普及，图片成为最重要的一种信息载体，在工作生活中扮演了重要角色，通过高清图片获取图片的信息内容，随时随地欣赏艺术作品成为可能，因此如何描述图片质量，分辨率至关重要。图片主要从“来源”到“展示”分成以下四个应用场景。</p><img src="'+E+'" alt="图片" style="zoom:50%;"><ul><li>（1）采集</li></ul><p>相机或扫描仪通过光电反应，将物体的信息通过数字信号转变成图像信息，存储而来的图片文件，分辨率取决于光电反应传感器的信号单元尺寸，一般用“像元”表示。</p><img src="'+B+'" alt="相机入门 无反和单反相机到底有什么区别_手机新浪网"><ul><li>（2）创建</li></ul><p>由计算机创建的数字图像文件，如画图软件或其他软件输出或导出保存的文件，分辨率根据需要人为设置。</p><img src="'+A+'" alt="图片" style="zoom:50%;"><ul><li>（3）显示</li></ul><p>由显示器显示屏幕通过显示单元对数字信号进行解析，模拟显示出来的图片信息。分辨率取决于显示单元的物理尺寸，如液晶屏的液晶单元尺寸。</p><img src="'+z+'" alt="图片" style="zoom:50%;"><ul><li>（4）输出</li></ul><img src="'+I+'" alt="图片" style="zoom:50%;"><h4 id="_2-4-分辨率与像素是一样的嘛" tabindex="-1">2.4 分辨率与像素是一样的嘛 <a class="header-anchor" href="#_2-4-分辨率与像素是一样的嘛" aria-label="Permalink to &quot;2.4 分辨率与像素是一样的嘛&quot;">​</a></h4><img src="'+F+'" alt="图片" style="zoom:50%;"><p>在数字时代，我们经常被各种炫目的技术参数所迷惑，其中分辨率无疑是其中之一。商家们常常用它来展示产品的卓越品质，但实际上，分辨率往往和像素混淆。</p><p>分辨率和像素并不是一回事。虽然它们在某种程度上有所关联，但它们的意义截然不同。分辨率是指图片或显示设备的清晰度和细腻程度，是一种比值，是信息密度的概念，而像素则是构成图像的基本单位，是信息量的概念。</p><p><strong>分辨率=像素值/尺寸</strong></p><p>在日常生活中，我们经常会看到各种显示器宣传自己的分辨率达到了2K或4K，而相机则会宣传自己的像素高达800万、2000万甚至1亿。这些数字看起来非常吸引人，但实际上，它们并不能真实反映设备的实际性能。因为，分辨率和像素并不能完全代表图像的质量。</p><img src="'+D+'" alt="图片" style="zoom:50%;"><p>作为图像信息采集的工具，相机和手机的传感器尺寸和像元尺寸（单元尺寸）直接决定了图像的质量。传感器的感光单元数量决定了一次可采集的图像总像素，而感光单元的物理尺寸则决定了其获取光信息的质量。如果感光单元太小，其获取的光信息量就会受到限制，导致图像质量无法显著提升。如下图：</p><img src="'+q+'" alt="image-20240703074658024" style="zoom:35%;"><p>感光单元上有大量的滤色片，这个其实之前学习RAW格式文件的时候有了解过：</p><img src="'+C+'" alt="image-20240703074611472" style="zoom:50%;"><p>因此，我们不能仅仅关注像素数量而忽视了像素质量。一台手机虽然宣称其像素高达5000万、8000万甚至一亿，但如果其传感器尺寸很小且像素单元被过度压缩，那么其图像质量可能并不会显著提高。因为像素单元的尺寸限制了其能够采集到的光信息量，导致图像质量无法得到有效提升。</p><p>又比如办公用的扫描仪，通常办公扫描仪可以调整扫描分辨率到600dpi或1200dpi，但实际扫描出来的图片差强人意，虽然扫出来的图片的确是1200dpi，但为什么还是模糊的呢？</p><img src="'+G+'" alt="图片" style="zoom:50%;"><p>因为图片信息并不是有效的，硬件的可采集的有效像素是固定的，提高分辨率只是人为通过算法插值进行扩充增加的像素，增加的像素并没有消除不确定，而是不确定的体现，图片的信息不确定造成图片仍然是模糊的。普通扫描仪调节分辨率只有量变并没有质变。</p><p>总之，分辨率和像素虽然在一定程度上有所关联，但它们的意义并不相同。我们不能被表面的数字所迷惑而忽视了实际的图像质量。在选择显示设备或相机时，我们应该更加关注其感光单元的尺寸和数量以及整体的图像处理技术而不仅仅是看像素数量。只有这样，我们才能真正享受到高质量的数字图像带来的视觉盛宴。</p><h4 id="_2-5-分辨率与像素和尺寸的换算" tabindex="-1">2.5 分辨率与像素和尺寸的换算 <a class="header-anchor" href="#_2-5-分辨率与像素和尺寸的换算" aria-label="Permalink to &quot;2.5 分辨率与像素和尺寸的换算&quot;">​</a></h4><p>图片的尺寸、分辨率、像素之间存在的公式关系：<strong>分辨率=总像素/总尺寸</strong></p><p>因此图片总像素不变的情况下，尺寸和分辨率成反比。也就是说同一张图片，分辨率越大，尺寸越小，尺寸越大，分辨率越小。</p><p>1英寸大约是2.54cm，当分辨率是300dpi时，上图图片尺寸和分辨率的具体的计算等式为：450像素/(3.81/2.54英寸) = 299.9999dpi。</p><img src="'+S+'" alt="图片" style="zoom:50%;"><p>当不改变像素量前提下，分辨率是72dpi时，上图图片尺寸和分辨率的具体的计算等式为：450像素/(15.88/2.54英寸) = 71.97733dpi。但如果直接拉大图片，不考虑**“真实像素”<strong>，增加分辨率的同时，人为增加像素，我们得到的图片就是软件通过算法模拟自动添加的像素信息，但这种信息是不确定的，也是不真实的像素，故而我们得到的最终图片并不能“清晰”或“真实”，当然目前AI人工智能在图片放大处理中引入了大量的计算机的学习能力，能够模拟较为准确的新增像素信息，但也仅仅是模拟，是消除信息不确定性的一种手段，并不能取代</strong>“真实像素”<strong>。在特定场合下可以使用，但</strong>“原始图片”**在生成的那一瞬间，图片质量就已然确定了，后期是无法改变图片信息的本质。</p><img src="'+M+'" alt="图片" style="zoom:50%;"><h4 id="_2-6-如何正确使用分辨率" tabindex="-1">2.6 如何正确使用分辨率 <a class="header-anchor" href="#_2-6-如何正确使用分辨率" aria-label="Permalink to &quot;2.6 如何正确使用分辨率&quot;">​</a></h4><p>由于分辨率是一种图片质量的技术参数，出于商业的考虑，常常与像素(点)混淆，只有深刻理解<strong>分辨率是有效图像信息的信息密度的参数</strong>，才可以避免对分辨率的误判。</p><ul><li><strong>分辨率涉及的印刷分辨率</strong></li></ul><img src="'+W+'" alt="图片" style="zoom:50%;"><p>一般的广告喷绘采用72dpi的分辨率进行喷绘，从而达到大尺寸的输出效果。虽然分辨率很低，打印出来远看时人眼的感受是清晰的，但一旦近距离观看会看到画面的颗粒感，这就是信息密度在不同距离上的反应，同样数量的点在不同尺度下的分辨率是不同的。以人眼分辨为界限，高于人眼分辨率的就会平滑，低于人眼分辨率就会看见颗粒间隙。</p><p>近距离观察的印刷件，印刷分辨率一般是人眼分辨率178DPIx2（安全系数）≈350DPI，文件的分辨率应不低于350DPI。</p><img src="'+v+'" alt="图片"><p>因此输出打印分辨率的设置与人眼观察距离有关。根据应用场景设置合适的打印分辨率是最主要的考虑因素。而获取图片时扫描分辨率的设置就要根据印刷分辨率来设置。</p><ul><li><strong>分辨率涉及的显示器的显示分辨率</strong></li></ul><img src="'+N+'" alt="image-20240704073844279" style="zoom:50%;"><p>一台24英寸显示屏显示比例器16:10，分辨率1920x1200像素，其宽度为20.35英寸（51.69cm），高度为12.72英寸(32.31cm)，真实分辨率应该是总的像素点数量/总显示尺寸，如宽度方向分辨率≈1920/20.35≈94.3 像素点/英寸（PPI），高度方向分辨率≈1200/12.71≈94.3像素点/英寸（PPI）。因此该显示屏显示分辨率为94像素点/英寸（PPI），也就是一英寸可以显示94.3个像素点。</p><p>一台27英寸显示器显示比例16:9，分辨率2560 x 1440 像素，宽度23.53英寸（59.77cm），高度13.24英寸（33.62cm）。宽度方向分辨率≈2560/23.53≈108.8像素点/英寸（PPI），高度方向分辨率≈1200/13.24≈108.8像素点/英寸（PPI）。因此该显示屏显示分辨率为108dpi，也就是一英寸可以显示108.8个像素点。</p><p>由上参数，抛开其他因素，单从分辨率角度，可以知道该27英寸的显示屏的显示效果优于24英寸显示屏，显示更细腻，细节更丰富。如果屏幕分辨率达到或超过人眼分辨率178DPI，则可以称之为视网膜显示屏，因为这样的屏幕的细腻度人肉眼是无法看见明显的颗粒感的，人的肉眼感受就是显示细腻清晰。</p><ul><li><strong>打印分辨率和扫描分辨率的对应关系</strong></li></ul><p>因为图片的像素是有限量的，图片的放大不能无限度放大，放大到一定程度就会看到单个像素单元，看到的就是单个像素颗粒，就出现锯齿状马赛克。给人的感觉就是图片不清晰，因此在创建图片时要考虑到今后使用的图片应用场景，需要放大到何种程度，由此反推出具体的尺寸和分辨率。</p><img src="'+V+'" alt="图片" style="zoom:50%;"><p>比如，我们需要将一幅尺寸20cmx30cm的作品放大打印到60x90cm，如何设置扫描分辨率呢？首先，我们知道60x90cm的画面比20x30cm的画面放大了3倍，因此，若已知打印精度要求300dpi，我们要扫描时的分辨率应该是3x300dpi=900dpi，即按原尺寸900dpi进行扫描获取高清图片。</p><p>又比如，我们已知一幅尺寸20x30cm的300dpi的图片，想要用输出分辨率72dpi输出，那最大能输出多大的图片呢？分辨率72dpi/300dpi的比值和图片大小比值一致，因此72dpi图片输出尺寸是20/（72/300）x30/（72/300）cm，计算得出约等于83.3x124.9cm</p><img src="'+K+'" alt="图片" style="zoom:50%;"><blockquote><p>扫描的分辨率要求多少合适？</p><p>原则上和输出分辨率有直接关系，输出分辨率的上限即扫描分辨率上限，但不知道输出分辨率的情况下，尽可能的提高扫描分辨率。比如艺术微喷高清打印机的墨点数量1.33英寸有800个墨点，分辨率达到了800/1.33=601.5dpi。也就是在601.5dpi以内的图片都可以真实还原。因此配合该型号的打印机扫描分辨率可以提高到600dpi，而如果只考虑到人眼分辨率，178dpi，打印分辨率乘以安全系数2，178*2≈350dpi。如果户外喷绘打印分辨率只需要72dpi就可以的情况下，扫描分辨率就有非常大的裁剪量。使用低分辨率输出时，当通过放大镜放大观看打印稿时，很容易就可以看到喷墨墨点，如果要追求更高的打印效果，当然是打印分辨率越高越好，这就要求图片扫描时的分辨率足够高，这样就能够发辉高清打印设备的优势。</p></blockquote><h3 id="_3-720p、1080p、2k、4k" tabindex="-1">3. 720P、1080P、2K、4K？ <a class="header-anchor" href="#_3-720p、1080p、2k、4k" aria-label="Permalink to &quot;3. 720P、1080P、2K、4K？&quot;">​</a></h3><p>我我们在购买电脑显示器，或者是录制视频，播放视频的时候总会看到这样720P、1080P、2K、4K这样的“分辨率”，这个分辨率与图片的分辨率起始是有所差别的，其实可以叫做显示分辨率。那这些分辨率都是什么意思呢？</p><ul><li><p>P：720P，1080P等，表示的是“视频像素的总行数”，比如，720P表示视频有720行的像素，而1080P则表示视频总共有1080行像素数，1080P分辨率的摄像机通常像素数是1920*1080。“P”本身表示的是“逐行扫描”，是Progressive的缩写，相对于隔行扫描（Interlaced）。</p></li><li><p>K：2K，4K，6K，8K等，表示的是“视频像素的总列数”，如<a href="https://www.wikiwand.com/zh-cn/4K" target="_blank" rel="noreferrer">4K分辨率 - Wikiwand</a>, 表示的是视频有4000列像素数（或者说横向显示的像素数量），具体是3840或4096列。在电视和消费的媒体中，3840×2160（4K <a href="https://www.wikiwand.com/zh-cn/%E8%B6%85%E9%AB%98%E7%95%AB%E8%B3%AA%E9%9B%BB%E8%A6%96" target="_blank" rel="noreferrer">UHD</a>）是主流的4K标准，而电影放映行业使用的是4096×2160（DCI（英语：<a href="https://en.wikipedia.org/wiki/Digital_Cinema_Initiatives" target="_blank" rel="noreferrer">Digital Cinema Initiatives</a>） 4K）。</p></li><li><p>MP：是像素总数，即像素的行数（P）及列数(K)相乘后的结果（百万像素），英文为Mega Pixels，缩写为MP。比如，1080P摄像机是1920像素与1080像素相乘，得到2MP（百万像素）的像素总数。</p></li></ul>',167)])])}const Y=e(R,[["render",T]]);export{U as __pageData,Y as default};
